/**
 * Soft WASM-init for `tnajw/full` (browser target). Wraps tnaw/web's
 * hard `initTnaw` in a try/catch so a failed WASM load doesn't throw.
 */
import { initTnaw, isTnawReady } from '../wasm/index-web.js';

let _initPromise: Promise<boolean> | null = null;

export async function initWasm(): Promise<boolean> {
  if (isTnawReady()) return true;
  if (_initPromise) return _initPromise;
  _initPromise = (async () => {
    try {
      await initTnaw();
      return isTnawReady();
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[tnajw/full] WASM init failed; dispatchers will use TS fallback:', err);
      return false;
    }
  })();
  return _initPromise;
}

export function isWasmEnabled(): boolean {
  return isTnawReady();
}
